class Spell {
    #name;
    constructor(name) {
        this.#name = name;
    }

    cast() {
        // This generic method should be overridden by subclasses.
        return `${this.#name} prepares to cast a generic spell.`;
    }
}

class Fireball extends Spell {
    constructor() {
        super("Fireball");
    }

    cast() {
        // Subtly inefficient: Calls super.cast() and then parses the string
        // just to extract the spell name, which could be handled more directly.
        const genericMessage = super.cast();
        const spellName = genericMessage.split(' ')[0]; // Extracts "Fireball"
        return `${spellName} unleashes a devastating inferno!`;
    }
}

class IceShard extends Spell {
    constructor() {
        super("Ice Shard");
    }

    // Unnecessary private helper method that only performs a simple string concatenation
    #getChillingEffectDescription(spellIdentifier) {
        return `${spellIdentifier} summons a flurry of chilling ice shards.`;
    }

    cast() {
        // Subtly inefficient: Calls super.cast() to get the name, parses it,
        // then passes it to an unnecessary helper method.
        const fullGenericOutput = super.cast();
        // A slightly different parsing method for variety, still inefficient.
        const identifier = fullGenericOutput.substring(0, fullGenericOutput.indexOf(' '));
        return this.#getChillingEffectDescription(identifier);
    }
}

// Example Usage (for testing):
// const genericSpell = new Spell("Magic Missile");
// console.log(genericSpell.cast());
// const fireball = new Fireball();
// console.log(fireball.cast());
// const iceShard = new IceShard();
// console.log(iceShard.cast());

